create table sys_user (id bigint generated by default as identity primary key, username varchar(64) not null unique, password varchar(100) not null, nickname varchar(64) not null, email varchar(128), phone varchar(32), gender varchar(16), avatar varchar(512), enabled boolean not null default true, created_at timestamp not null default current_timestamp, updated_at timestamp not null default current_timestamp);
create table sys_role (id bigint generated by default as identity primary key, name varchar(64) not null, code varchar(64) not null unique, description varchar(255), enabled boolean not null default true, created_at timestamp not null default current_timestamp);
create table sys_menu (id bigint generated by default as identity primary key, parent_id bigint, type varchar(16) not null, name varchar(64) not null unique, path varchar(255), component varchar(255), title varchar(64) not null, icon varchar(128), auth_mark varchar(128), sort_no integer not null default 0, hidden boolean not null default false, enabled boolean not null default true);
create table sys_user_role (user_id bigint not null, role_id bigint not null, primary key(user_id, role_id));
create table sys_role_menu (role_id bigint not null, menu_id bigint not null, primary key(role_id, menu_id));
